      template:
        "SELECT CASE WHEN total >= {1} THEN 'premium cart'\n              WHEN total >= 200 THEN 'core cart'\n              ELSE 'value cart' END AS cart_tier,\n       {2}(*) AS orders,\n       ROUND({3}(total), 2) AS avg_total\nFROM orders\nGROUP BY cart_tier\nORDER BY avg_total {4};",
